<div class="form-grid"><label class="field sm:col-span-2"><span>Quality <output data-for="quality">82</output>%</span><input type="range" name="quality" min="1" max="100" value="82"></label><label class="field"><span>Width (px)</span><input type="number" name="width" min="1" max="10000" placeholder="Original"></label><label class="field"><span>Height (px)</span><input type="number" name="height" min="1" max="10000" placeholder="Original"></label><label class="check"><input type="checkbox" name="preserve_aspect" value="1" checked><span>Preserve aspect ratio</span></label><label class="check"><input type="checkbox" name="prevent_enlarge" value="1" checked><span>Prevent enlargement</span></label><label class="field sm:col-span-2"><span>Output format</span><select name="format"><option value="webp">WebP</option><option value="jpg">JPG</option><option value="png">PNG</option></select></label></div>
